/* TNM World Wrestling Report: USWA (United States Wrestling Association).
   Everything the site shows for this promotion lives in this file. */

P.uswa = {"short": "USWA", "name": "United States Wrestling Association", "home": "Memphis, TN", "c": "var(--uswa)", "status": "The Red, White and Bruised Tour drew 4,500 to Louisville Gardens. Kerry stole the pin from Bret, Austin and Studd tore the place up, and Flair vs. Funk is set for the Sportatorium 7/20. Dallas Iron Man II on 8/17.", "stat": ["$273,520", "July revenue (gate + merch)"], "titles": [["Unified World", "Bret Hart", "Retained over Kerry Von Erich at Star Wars 7/1 (Sharpshooter, 30:16). Iron Man II in Dallas 8/17."], ["Southern Heavyweight", "Steve Austin", "Retained over Brickhouse Brown 7/1. Diamond Studd debuted after and is coming for it."], ["Television", "Bill Dundee", "Won the one-night tournament over Brickhouse Brown. Jamie Dundee challenges 8/3."], ["Tag Team", "Unresolved", "Tully Blanchard debuted as Scott Steiner's partner 7/1 after Fuller was ruled out."]], "factions": [["Paul Ellering's stable", "Andre the Giant, with Stan Hansen and Dan Spivey recruited by 7/27. Jamie Dundee ringside. Kawada turned Ellering down."], ["The Texas Outlaws", "Renamed from the Texas Bunch 7/3. Terry Funk, Chris Adams, Eric Embry, Tom Prichard and Kevin Von Erich, with Dutch Mantell as an ally. Their target: Ric Flair."], ["Hot Stuff International", "Steve Austin, Eddie & Doug Gilbert, Missy Hyatt. Dennis Condrey gave notice 7/13. Austin thought Missy knew about Diamond Studd, but she helped him against Studd in Louisville."], ["The Moondogs", "Rex, Spot and Cujo turned on Mark Canterbury at Star Wars and now ride with the Honky Tonk Man."], ["The New Kids", "Brian Christopher & Tony Williams. Young team in Bill Dundee's corner. Lost to Hansen & Spivey in Louisville 7/13."], ["The Memphis Mafia", "Dirty White Boy, Rex King and Sweet Daddy Falcone. Disqualified in Louisville 7/13 when Hansen & Spivey ran in on Steiner & Tully. DWB isn't happy about it."], ["Calculated Force", "Scott Steiner & Tully Blanchard, the USWA Tag Team Champions. Robert Fuller saved them from Hansen & Spivey in Louisville, even though Tully has the spot he wanted."]], "stories": [["Kerry Steals the Pin", "Kerry tornado-punched Andre out of the ring in Louisville 7/13, pulled Bret off Jamie Dundee and pinned Jamie with a backslide. Bret: \"That's fine.\" Iron Man II is 8/17."], ["Match Observations: Louisville", "The Observer on 7/13: $67,500 for a house show, Austin–Studd at ****, a 5:38 tag title tease and Dennis Condrey's notice."], ["Flair Crashes Star Wars", "Ric Flair debuted at ringside 7/1 and cost Kevin Von Erich his match with Terry Funk. The show closed on Flair staring down Funk and Kevin. He still has Big Gold."], ["Bret & Kerry", "Bret beat Kerry at Star Wars, then Andre put Kerry to sleep in Memphis 7/6. Kerry and Bret beat Andre & Jamie in Louisville 7/13, but Kerry took the pin from Bret. Iron Man II in Dallas 8/17."], ["Backstage Notes: Memphis", "The Observer on the 7/6 show: a $54,000 angle show, the Flair mystery, Tully's belt, Jamie's chain and Kawada going home."], ["Andre Puts Kerry to Sleep", "Andre beat Kerry with the bear hug 7/6. Ric Flair checked on Kerry after and whispered in his ear."], ["The Texas Outlaws", "Funk renamed the Texas Bunch on Worldwide 7/3 with Kevin Von Erich at his side. Both blame Ric Flair for the Star Wars finish."], ["Studd vs. Austin", "Diamond Studd debuted at Star Wars and cleared HSI. Their first match, Louisville 7/13, went 21 minutes to a double count-out (****). Missy helped Austin; Studd powerbombed him through a table."], ["Jarrett vs. the Gilberts", "Eddie Gilbert won the Star Wars cage with a piledriver through the ropes. Jarrett still holds the #1 contender spot."], ["Honky vs. Canterbury", "The Moondogs turned on Canterbury at Star Wars and joined Honky. \"I ain't a manager anymore.\" Steel cage in Memphis 8/31."], ["A Different Sam Houston", "No smile, no hat wave. Houston says he's been overlooked and named Scotty Flamingo as the problem."], ["Power Pro Wrestling: Level Up!", "Development brand launched 6/30 in Nashville: Modest, Awesome, Bagwell, Johnny B. Badd, the Thrillseekers, Helms, Tatanka, Gilbertti, D-Von and more. Rocky Johnson is the mentor."]], "desk": ["Dennis Condrey gave notice 7/13. Last date not set.", "Memphis Mafia took a DQ for Hansen & Spivey's run-in: Mafia vs. Hansen & Spivey?", "Steiner & Tully's first match as Calculated Force went only 5:38.", "Flair's first program: Funk and Kevin? And how does Big Gold sit next to the Unified Title?", "Dick Slater injured, 6 more cards.", "Kawada / Scotty Flamingo TV thread unresolved.", "Autumn Armageddon has no date or card.", "September AWA-territory tour: St. Paul, Milwaukee, Chicago, Green Bay, Las Vegas."], "roster": [["Ric Flair", "New signing from WCW. Has Big Gold"], ["Andre the Giant", ""], ["Bret Hart", ""], ["Terry Funk", "Texas Outlaws"], ["Kerry Von Erich", ""], ["Kevin Von Erich", "Texas Outlaws"], ["Jerry Lawler", ""], ["Stan Hansen", "Also AJPW. Ellering"], ["Eddie Gilbert", ""], ["Dan Spivey", "Also AJPW. Ellering"], ["Scott Steiner", ""], ["Tully Blanchard", "Steiner's partner. Debuted 7/1"], ["Bill Dundee", "TV Champion"], ["Robert Fuller", ""], ["Dutch Mantell", ""], ["Diamond Studd", ""], ["Sam Houston", ""], ["Jeff Jarrett", ""], ["Doug Gilbert", ""], ["Dennis Condrey", ""], ["Honky Tonk Man", ""], ["Steve Austin", "Southern Champion"], ["Dick Slater", "INJ: 6 more cards"], ["Chris Adams", ""], ["Dirty White Boy", ""], ["Scotty Flamingo", ""], ["Jimmy Valiant", ""], ["Brickhouse Brown", ""], ["Rex King", "Re-signed: 150 cards"], ["Tom Prichard", ""], ["Eric Embry", ""], ["The Spellbinder", ""], ["Nightmare Danny Davis", "The Nightmares"], ["Nightmare Ken Wayne", "The Nightmares"], ["Mark Canterbury", ""], ["Moondog Cujo", "Moondogs · leaving, won't renew"], ["El Hijo Del Santo", ""], ["Moondog Spot", "Moondogs"], ["Eddie Guerrero", "Also CMLL"], ["Moondog Rex", "Moondogs"], ["Sweet Daddy Falcone", ""], ["Scott Taylor", ""], ["Jamie Dundee", "w/ Ellering"], ["Rob Zakowski", ""], ["Jim Powers", "Debuted 7/3"], ["Tony Williams", ""], ["Brian Christopher", ""], ["Toshiaki Kawada", "Leaving: AJPW recalled him"], ["The Masked Avenger", ""], ["Oliver Peters", ""], ["Red Tyler", ""], ["Alan Martin", ""], ["Paul Ellering", "Manager"], ["Missy Hyatt", "Manager / HSI"]], "departures": [["Dennis Condrey", "Gave notice 7/13/91. Hot Stuff International."], ["Rick Steiner", "Left USWA (now WCW)"], ["Moondog Cujo", "Contract up, won't renew"], ["Toshiaki Kawada", "Wanted to re-sign; All Japan asked for him back full-time"]], "asOf": "1991-07-13"};

E.push(...[{"d": "1991-07-01", "p": "uswa", "city": "Memphis, TN", "venue": "Mid South Coliseum", "type": "USWA Star Wars 1991 (PPV)", "gate": "10,085 · $121,020", "rate": "***1/4", "big": 1, "link": "STAR_WAR", "m": [["Pre-show: El Hijo Del Santo vs. Scott Taylor", "Santo (surfboard). USWA debut", "****1/4"], ["Pre-show: Mark Canterbury vs. Honky Tonk Man", "Canterbury by DQ. Moondogs turn on Canterbury, join Honky", "3/4*"], ["Four corners: Nightmares vs. HSI (Condrey & D. Gilbert) vs. New Kids vs. Zakowski & Houston", "Nightmares (Ken Wayne, Flying Stomp). 1:06:21", "***1/2"], ["Jamie Dundee & Andre vs. Bill Dundee & Jimmy Valiant", "Andre pins Valiant (elbow drop)", "*"], ["Texas Bunch & Dutch Mantell vs. Memphis Mafia & Jerry Lawler", "Embry pins Rex King (piledriver)", "***3/4"], ["Southern Title: Steve Austin (c) vs. Brickhouse Brown", "Austin retains (Stun Gun). Diamond Studd debuts after", "***"], ["Terry Funk vs. Kevin Von Erich", "Funk (spinning toe hold). Flair debuts at ringside", "*****1/4"], ["Scott Steiner & Tully Blanchard vs. Stan Hansen & Dan Spivey", "Steiner by DQ. Blanchard debuts", "*1/4"], ["Cage: Eddie Gilbert vs. Jeff Jarrett", "Gilbert (piledriver through the ropes)", "****1/4"], ["Unified Title: Bret Hart (c) vs. Kerry Von Erich", "Bret retains (Sharpshooter). 30:16", "****1/4"]], "n": ["Kevin Von Erich now officially in the Texas Bunch. Show closes on Flair vs. Funk & Kevin staredown.", "Kerry raised Bret's hand, but looked full of self-doubt.", "Rocky Johnson introduced as a special guest (Power Pro mentor hint)."]}, {"d": "1991-07-03", "p": "uswa", "city": "Jonesboro, AR", "venue": "Earl Bell Community Center", "type": "Worldwide (S1 E11) · Red, White and Bruised Night 1", "gate": "600 · $3,000", "rate": "***", "m": [["Eddie Guerrero vs. Rob Zakowski", "Guerrero (frog splash), 11:11", "***1/2"], ["Chris Adams vs. Jim Powers", "Adams (superkick), 5:27. Powers debut", "**3/4"], ["Honky Tonk Man vs. Oliver Peters", "HTM (Shake, Rattle 'n' Roll), 2:24", ""], ["New Kids & Scott Taylor vs. Vang, Burt & Rich", "T. Williams pins Rich (cross body), 6:15", ""], ["Jimmy Valiant & Bill Dundee vs. Dirty White Boy & Rex King", "Valiant (sleeperhold on King), 10:22", "***"]], "n": ["Texas Bunch renamed the Texas Outlaws. Kevin Von Erich blames Flair.", "Sam Houston calls out Scotty Flamingo.", "Marlin gives Kerry Andre on 7/6."]}, {"d": "1991-07-06", "p": "uswa", "city": "Memphis, TN", "venue": "Mid South Coliseum", "type": "Championship Wrestling (Live TV) · Red, White and Bruised Night 2", "gate": "4,500 · $54,000 (+ $2,000 merch)", "rate": "**1/2", "m": [["Sam Houston vs. Johnny Rich", "Houston (tiger suplex), 6:14. Flamingo mouths off after", ""], ["Diamond Studd vs. Dennis Condrey", "Studd (Final Reckoning), 7:04. Studd's USWA debut match", "*1/2"], ["Scott Taylor & the New Kids vs. Santo, Spellbinder & Masked Avenger", "Taylor pins Avenger (Fall of the Angels), 8:24", ""], ["Kerry Von Erich vs. Andre the Giant (w/ Ellering)", "Andre: Kerry passed out in the bear hug, 14:43", "**3/4"]], "n": ["Steiner & Tully Blanchard made official as tag champions. Fuller angry.", "Jamie Dundee attacks Jimmy Valiant with a chain.", "Ric Flair checks on Kerry after the main event and whispers to him."]}, {"d": "1991-07-10", "p": "uswa", "city": "Evansville, IN", "venue": "Veterans Memorial Coliseum", "type": "Worldwide · Red, White and Bruised Night 3", "gate": "2,000 · $16,000 + $1,000 merch", "rate": "**1/2", "m": [["Scotty Flamingo vs. Sweet Daddy Falcone (Invitational, match 1)", "Flamingo (flying sunset flip), 8:14", "***1/2"], ["Moondogs vs. Jos LeDuc & Kerry Brown", "Rex pins Brown (Dog Bone to the Head), 5:13", ""], ["Jim Powers vs. Rob Zakowski", "Powers (flying cross body). First USWA win", "**1/2"], ["TV Title: Bill Dundee (c) vs. Chris Adams", "Dundee retains (piledriver), 17:10", "**1/2"]], "n": ["Flamingo announces the Flamingo Invitational Series.", "Marlin books Moondog Spot vs. Mark Canterbury for 7/17 Jonesboro.", "Eddie Gilbert tells Austin there are \"bigger prizes\"; Missy keeps the peace.", "Hansen & Spivey want a dog collar rematch, no DQ."]}, {"d": "1991-07-13", "p": "uswa", "city": "Louisville, KY", "venue": "Louisville Gardens", "type": "House show · Red, White and Bruised Night 4 (3 hours, not televised)", "big": 1, "m": [["Jim Powers vs. Sweet Daddy Falcone", "Powers (flying cross body), 15:08", "***1/2"], ["Flamingo Invitational #2: Scotty Flamingo vs. Scott Taylor", "Flamingo (low blow), 17:09", "**1/2"], ["Jeff Jarrett vs. Doug Gilbert", "Jarrett by submission (Las Vegas Leglock), 17:32", "***3/4"], ["Stan Hansen & Dan Spivey vs. the New Kids", "Hansen pins Williams (powerbomb), 18:06", "***1/4"], ["Calculated Force (Steiner & Tully) vs. Memphis Mafia (DWB & Rex King)", "Steiner & Tully by DQ, 5:38", "**3/4"], ["The Nightmares vs. Eric Embry & Tom Prichard", "Ken Wayne pins Prichard (Flying Stomp), 15:29", "*"], ["Steve Austin vs. Diamond Studd (non-title)", "Double count-out, 21:15", "****"], ["Kerry Von Erich & Bret Hart vs. Andre the Giant & Jamie Dundee", "Kerry pins Jamie (backslide), 26:55", "***"]], "gate": "4,500 · $67,500 + $9,000 merch", "rate": "***", "n": ["Ric Flair: \"That's between me and Kerry.\" Flair vs. Terry Funk set for Dallas 7/20; Funk and Kevin answer from the entrance.", "Eddie Gilbert, ringside for Doug, says Jarrett's title shot is his.", "Sam Houston stares down Flamingo from the aisle.", "Hansen & Spivey run in on Steiner & Tully (Mafia DQ), attack with a chain and dog collar; Robert Fuller makes the save.", "Missy interferes against Studd; Studd powerbombs Austin through a table.", "Kerry pulls Bret off Jamie and steals the pin. Bret: \"That's fine.\"", "Dennis Condrey gives notice."]}, {"d": "1991-07-17", "p": "uswa", "city": "TBD", "venue": "", "type": "Spot show"}, {"d": "1991-07-20", "p": "uswa", "city": "Dallas, TX", "venue": "Sportatorium", "type": "Championship Wrestling"}, {"d": "1991-07-24", "p": "uswa", "city": "Evansville, IN", "venue": "Veterans Memorial Coliseum", "type": "TV taping"}, {"d": "1991-07-27", "p": "uswa", "city": "Nashville, TN", "venue": "Fairgrounds", "type": "Syndicated taping", "n": ["Ellering formally brings in Hansen & Spivey."]}, {"d": "1991-07-31", "p": "uswa", "city": "Jonesboro, AR", "venue": "Earl Bell Community Center", "type": "TV taping"}, {"d": "1991-08-03", "p": "uswa", "city": "", "venue": "", "type": "TV Title: Bill Dundee vs. Jamie Dundee"}, {"d": "1991-08-17", "p": "uswa", "city": "Dallas, TX", "venue": "Reunion Arena", "type": "Echoes of Glory: Bret vs. Kerry Iron Man II", "gate": "16,000 · $320,000", "big": 1}, {"d": "1991-08-31", "p": "uswa", "city": "Memphis, TN", "venue": "Mid South Coliseum", "type": "Cage: Honky Tonk Man vs. Mark Canterbury"}]);

Object.assign(ARTICLES, {"uswa-observer-louisville-0713": {"p": "uswa", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-15", "region": "Memphis Report", "kicker": "USWA · House show · Louisville, July 13", "title": "Match Observations: Louisville", "dek": "$67,500 for a house show. Austin and Studd steal it at ****, Kerry steals a pin from Bret, Steiner and Tully get 5:38, and Dennis Condrey gives notice.", "factTitle": "The Numbers", "facts": [["Venue", "Louisville Gardens, Louisville, KY"], ["Date", "July 13, 1991 · house show"], ["Attendance", "4,500"], ["Average ticket", "$15.00"], ["Gate", "$67,500 + $9,000 merch"], ["Card rating", "***"], ["Best match", "Austin vs. Studd, ****"]], "body": [["h", "The gate"], ["p", "The USWA drew 4,500 to Louisville Gardens on 7/13 at a $15 average for $67,500, plus about $9,000 in merchandise at $2 a head. That's the best non-supershow gate of the month, beating the $54,000 they did for live TV at the Mid South Coliseum a week earlier, and it was a non-televised house show. The building holds about 6,000. Louisville has been one of their best towns for a couple of years, and a Kerry and Bret tag with Flair on the card is what fills it. The card was rated ***, tied with the 7/3 Jonesboro TV for the best of the tour since Star Wars."], ["h", "Powers and Falcone"], ["p", "Jim Powers vs. Sweet Daddy Falcone opened at ***1/2. That's two weeks in a row Falcone has had one of the best matches on the show in a losing effort, and Powers is 2-0 since his debut loss. Powers won with the flying cross body at 15:08 and Falcone shook his hand. The office is clearly behind Powers, and Falcone has quietly become the best hand in the territory at making people look good."], ["h", "Flamingo"], ["p", "Flamingo beat Scott Taylor with a low blow at 17:09, **1/2. Last week Flamingo beat Falcone clean, which didn't make sense for a heel. This week he cheated, so the Invitational now works the way it should. Sam Houston stood in the aisle and stared him down after, which is how they're building that one."], ["h", "Jarrett and the Gilberts"], ["p", "Jarrett vs. Doug Gilbert was the second-best match on the card at ***3/4, with Jarrett winning by submission with the Las Vegas Leglock at 17:32. Eddie Gilbert was at ringside and cut a promo after about beating Jarrett in the cage and wanting Jarrett's title shot. That's the setup for Eddie running in on Bret vs. Jarrett in Nashville on 7/27."], ["h", "Hansen & Spivey"], ["p", "Hansen & Spivey beat the New Kids in 18:06, ***1/4, with Hansen pinning Tony Williams after a powerbomb. Good, physical match. The New Kids lost but looked fine against two guys that size."], ["h", "Flair"], ["p", "Flair's promo was the centerpiece of the first half. He wouldn't say what he whispered to Kerry, and he confirmed Flair vs. Funk for Dallas. Funk and Kevin Von Erich came out to answer him, and the crowd was hot for all of it. It sold the Sportatorium show."], ["h", "Calculated Force"], ["p", "The champions' non-title match didn't do what the office wanted. Steiner and Tully, billed for the first time as Calculated Force, were supposed to show how they look as a team against the Memphis Mafia. It went 5:38 before Hansen and Spivey ran in and the Mafia were disqualified, rated **3/4. The post-match angle was fine: Hansen and Spivey went after the champions with a chain and dog collar, and Robert Fuller made the save even though Tully has the spot he wanted. That's another layer on Fuller. But we still don't know if Steiner and Tully click as a team. The other question is why the Mafia took the DQ for interference they had nothing to do with. If they want to do something with that, Dirty White Boy and Rex King against Hansen and Spivey is right there."], ["h", "The Nightmares"], ["p", "The Nightmares beat Embry and Prichard in 15:29, *, Ken Wayne with the Flying Stomp. It was the worst match on the card and went far too long for what it was. The Nightmares are supposed to be the number one contenders, and nobody in the building acted like it."], ["h", "Austin and Studd"], ["p", "Austin vs. Diamond Studd was ****, the best match on the show, going 21:15 to a double count-out. Missy Hyatt interfered on Austin's behalf while it was on the floor, then Studd powerbombed Austin through a table after the count. That's interesting, because the story has been Austin not trusting Missy, and tonight she saved him. Studd is getting over fast. Austin has the title, but Studd looks like the bigger star in this program right now."], ["h", "The main event"], ["p", "Kerry and Bret beat Andre and Jamie Dundee in 26:55, ***. Kerry tornado-punched Andre out of the ring, then pulled Bret off Jamie and pinned him with a backslide, with Paul Ellering interfering against Kerry along the way. It was long for Andre, and they kept him out of the ring for most of the closing stretch. The finish and Bret's \"that's fine\" afterward are the right setup for Iron Man II at Reunion Arena on 8/17."], ["h", "Condrey"], ["p", "Backstage, Dennis Condrey has given his notice and will be leaving the territory. Condrey has been part of Hot Stuff International, mostly in the four-way at Star Wars and as a TV opponent for Diamond Studd. He isn't a big loss to the cards, but he's a veteran who's been around this office a long time. HSI is down to Austin, the Gilberts and Missy."]]}, "uswa-diary-dwb-0713": {"p": "uswa", "series": "diary", "by": "Dirty White Boy", "date": "1991-07-13", "place": "I-65 South, somewhere past Elizabethtown", "kicker": "From the Road · Louisville, July 13", "title": "Five Minutes and Thirty-Eight Seconds", "dek": "Dirty White Boy finally got the tag team champions in Louisville. Then Hansen and Spivey took it away from him.", "factTitle": "The Night", "facts": [["Show", "USWA house show, Louisville Gardens"], ["Match", "Steiner & Tully d. Dirty White Boy & Rex King"], ["Finish", "DQ (Hansen & Spivey run-in), 5:38"], ["Rating", "**3/4"]], "body": [["p", "Five minutes and thirty-eight seconds. That's how long I got in the ring with the tag team champions of the world tonight. Five minutes and thirty-eight seconds, in front of 4,500 people in Louisville, and then two men I've never said ten words to come through the ropes and take it away from me."], ["p", "Rex and I were just getting warm. Steiner's built like a refrigerator and he hits like one. Tully's the smartest man I've ever locked up with. Every time I thought I had something, he was already two steps ahead. But we were in it. Rex hit Tully with a clothesline that I heard from across the ring. The people were starting to believe it might happen."], ["p", "Then Hansen and Spivey. I didn't call them. Rex didn't call them. Nobody in the Memphis Mafia called anybody. And the referee looks at me like I invited them to supper and waves the match off. Disqualified. The Mafia loses by DQ for something we never asked for. If those two think they can use our match to settle their business, they've got another thing coming."], ["p", "I'll give Robert Fuller this: he ran down there for the champions after Tully took his spot. I don't know if I'd have done it. Maybe that's why he's a good guy and I'm not."], ["p", "Stood in the curtain for the main event. Kerry Von Erich pulled the champ off Jamie Dundee and stole the pin right out from under him. Bret Hart said \"that's fine\" into the microphone, and I've been in this business long enough to know that when a man says \"that's fine\" like that, it isn't."], ["p", "Heard in the dressing room that Dennis Condrey gave his notice. Dennis has been in this business longer than some of these kids have been alive. He's one of the best tag team men there ever was. He didn't say much about it, just packed his bag like any other night. That's how the good ones go. No speeches."], ["p", "Rex is asleep in the passenger seat. Memphis by sunup. I keep thinking about those five minutes. Next time Hansen and Spivey want to start something in the middle of my match, they can deal with me first."]]}, "uswa-kerry-steals-the-pin": {"p": "uswa", "news": 1, "by": "USWA Magazine", "date": "1991-07-14", "region": "Memphis Report", "kicker": "USWA · Louisville Gardens, July 13", "title": "Kerry Steals the Pin", "dek": "Kerry and Bret beat Andre and Jamie Dundee, but Kerry took the pin from his partner. Flair vs. Funk is set, and Austin and Studd tore up Louisville.", "factTitle": "The Card", "facts": [["Main event", "Kerry & Bret d. Andre & Jamie (backslide), 26:55"], ["Best match", "Austin vs. Studd, double count-out, ****"], ["Next", "Flair vs. Funk, Dallas 7/20"]], "body": [["p", "Night four of the Red, White and Bruised Tour packed 4,500 fans into Louisville Gardens, and they went home with plenty to talk about. In a main event that went nearly twenty-seven minutes, Kerry Von Erich and Unified World Champion Bret Hart beat Andre the Giant and Jamie Dundee. But it was how they won that had the building buzzing."], ["p", "With Paul Ellering doing everything he could from the floor to slow Kerry down, the Modern Day Warrior finally turned the tide with a tornado punch that sent Andre crashing out of the ring. Bret had Jamie Dundee trapped in the middle of the ring and was going in for the finish when Kerry pulled him off, caught Jamie in a backslide, and took the pin himself at 26:55."], ["p", "A week after Andre put him to sleep in Memphis, it was the win Kerry needed. Bret didn't see it that way. On the mic afterward, the Hitman told his partner \"good win,\" then reminded everyone that he had Jamie beat before Kerry took the pin. \"That's fine,\" Bret said. Then he shook Kerry's hand once, walked up the aisle and never looked back. Kerry stayed behind and celebrated with the fans. Iron Man II at Reunion Arena on August 17 is a little more personal now."], ["h", "The Nature Boy Speaks"], ["p", "Ric Flair held court in the ring before intermission, Big Gold over his shoulder. Asked what he whispered to Kerry Von Erich in Memphis, Flair just smiled: \"That's between me and Kerry.\" Then he made it official. Next Saturday, at the Sportatorium in Dallas, Flair has his first USWA match, against Terry Funk."], ["p", "He didn't get the last word. Terry Funk and Kevin Von Erich walked out to the top of the entrance, and Funk told the Nature Boy the Sportatorium is his house. Kevin reminded Flair that he cost him at Star Wars. Nobody threw a punch, but Flair left through the crowd rather than walk past them."], ["h", "Austin and Studd Tear Up Louisville"], ["p", "Steve Austin and the Diamond Studd fought for more than twenty-one minutes, and the referee never got close to counting a pinfall. The brawl spilled to the floor, and when Studd started to take control on the outside, Missy Hyatt jumped in to help her man. Neither man made it back inside before the count of ten: a double count-out. Studd wasn't finished. He powerbombed Austin through a ringside table, and Missy could only stare at the wreckage. Austin keeps the Southern Title, but this one isn't over."], ["h", "Champions Robbed of A Finish"], ["p", "Scott Steiner and Tully Blanchard, the team now calling itself Calculated Force, were less than six minutes into their match with the Memphis Mafia when Stan Hansen and Dan Spivey stormed the ring. The referee threw the match out and disqualified Dirty White Boy and Rex King. Then Hansen and Spivey went to work on the champions with a chain and a dog collar until Robert Fuller ran in to make the save. Fuller made the save for the same men who took his tag title spot."], ["p", "Earlier, Hansen and Spivey sent a message of their own, beating the New Kids when Hansen powerbombed Tony Williams at 18:06. They want Steiner and Tully in a dog collar match, and after Louisville, they may get it."], ["h", "Jarrett Gets Even"], ["p", "Jeff Jarrett made Doug Gilbert submit to the Las Vegas Leglock in 17:32. Eddie Gilbert, at ringside for his brother, grabbed the mic afterward to remind everyone he beat Jarrett in the Star Wars cage, and said Jarrett's Unified Title shot belongs to him. Jarrett didn't answer. He didn't have to. Somebody was going to need help getting Doug to the back."], ["h", "Also In Louisville"], ["p", "Jim Powers opened the show with a strong win over Sweet Daddy Falcone, hitting a flying cross body at 15:08. Falcone shook his hand afterward. That's two straight wins for the newcomer. Scotty Flamingo made it two for two in his Invitational Series, but he needed a low blow to put away Scott Taylor at 17:09. Sam Houston watched it all from the aisle and stared Flamingo down on his way out. The Nightmares, the number one contenders to the tag titles, beat Eric Embry and Tom Prichard of the Texas Outlaws when Ken Wayne hit the Flying Stomp at 15:29."], ["h", "Next: Dallas"], ["p", "The tour moves to Jonesboro on Wednesday for Moondog Spot vs. Mark Canterbury, then to the Sportatorium in Dallas next Saturday for Ric Flair vs. Terry Funk."]]}, "uswa-memphis-tokyo-shuttle": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Memphis Report", "kicker": "USWA · Backstage", "title": "The Memphis–Tokyo Shuttle", "dek": "Stan Hansen and Dan Spivey are trying to be the USWA tag team challengers and All Japan regulars at the same time. Something has to give.", "body": [["p", "Stan Hansen and Dan Spivey are the most-traveled tag team in wrestling this summer. In Memphis, they're chasing Scott Steiner and Tully Blanchard for the tag titles and are about to join Paul Ellering's stable. In Japan, they're regulars on All Japan's Summer Action Series, working with Misawa's group and the Fantastics."], ["p", "It hasn't lined up cleanly. They missed All Japan's show in Niigata on July 7 because they were in the States, and the USWA had to settle for recorded comments from the two of them in Evansville. All Japan's plan has them back for the end of the tour, including Budokan on the 27th, which is also the weekend Ellering is supposed to bring them into his group on USWA TV."], ["h", "Who wins"], ["p", "Right now, All Japan pays better and draws bigger houses, and Hansen is one of Baba's most important foreigners. The USWA has the storyline. The word is that Jerry Jarrett is happy to work around the dates as long as the dog collar rematch for the tag titles happens in August. If it gets pushed back again, expect the Memphis office to start asking which promotion Hansen and Spivey actually work for."]], "facts": [["Team", "Stan Hansen & Dan Spivey"], ["USWA", "Tag title rematch; joining Ellering"], ["AJPW", "Summer Action Series"], ["Missed", "AJPW Niigata, 7/7"], ["Back in Japan", "Through Budokan, 7/27"]], "factTitle": "Two Countries"}, "uswa-big-gold": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Memphis Report", "kicker": "USWA · Backstage", "title": "Whose Belt Is It?", "dek": "Ric Flair walked into Memphis carrying the Big Gold belt. WCW says it wants it back.", "body": [["p", "When Ric Flair left WCW, he took the Big Gold belt with him, and he brought it to ringside at Star Wars on July 1. It's the most famous championship belt in the business, and right now it belongs to a man who doesn't work for the company that created it."], ["p", "The word out of Atlanta is that WCW has been in touch with Flair's people about getting the belt back, and that the argument is about money. Flair says he paid a deposit on the belt years ago that was never returned. WCW is about to crown a new World Champion at the Bash, Luger vs. Windham in a cage, and would rather the new champion not be wearing a different belt while Flair carries the real one around Memphis."], ["h", "Two World Champions"], ["p", "For the USWA, it's a gift. Bret Hart is the Unified Champion, and Flair walking around with Big Gold practically books itself. Flair makes his in-ring USWA debut against Terry Funk in Dallas on July 20, and the obvious question for the fall is whether he and Bret ever meet with both belts in the ring. If WCW gets the belt back before then, it changes the story. If not, the USWA has the best prop in wrestling."]], "facts": [["Belt", "Big Gold"], ["Held by", "Ric Flair (USWA)"], ["WCW", "New champion at the Bash, 7/14"], ["Dispute", "Flair's deposit"], ["Flair's debut", "vs. Terry Funk, Dallas, 7/20"], ["USWA champion", "Bret Hart (Unified)"]], "factTitle": "The Dispute"}, "uswa-jonesboro-report": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Worldwide · Jonesboro, July 3", "title": "Red, White and Bruised Opens", "dek": "Two nights after Star Wars, the USWA was back on TV in Jonesboro. Jimmy Valiant got a win, Eddie Guerrero had the match of the night, and the Texas Bunch has a new name.", "body": [["p", "Worldwide from the Earl Bell Community Center drew 600 for $3,000 on July 3. That's a normal Jonesboro house, and nobody expected more two nights after the biggest show of the year. It was Night 1 of the Red, White and Bruised Tour, four shows in eleven days that run through Memphis, Evansville and Louisville. The card came in at three stars, and most of the important stuff happened on the microphone."], ["h", "The matches"], ["p", "Jimmy Valiant and Bill Dundee beat Dirty White Boy and Rex King of the Memphis Mafia in the main event when Valiant put King to sleep with the sleeperhold at 10:22. Three stars. Valiant was pinned by Andre in his return at Star Wars, so this was the win he needed. The Mafia have now lost on back-to-back shows."], ["p", "The best match was Eddie Guerrero over Rob Zakowski with the frog splash at 11:11, three and a half stars. Guerrero is splitting time with CMLL and keeps having the best match on whatever card he's on."], ["p", "Jim Powers debuted and lost to Chris Adams, who hit the superkick at 5:27 (**3/4). Honky Tonk Man beat Oliver Peters in 2:24. The New Kids and Scott Taylor beat Jan Vang, Jody Burt and Johnny Rich when Tony Williams hit a flying cross body on Rich."], ["h", "The talking"], ["p", "Sam Houston opened the show with an interview nobody saw coming. No smile, no hat wave. He said he's tired of being overlooked and blamed Scotty Flamingo for poisoning the locker room. Terry Funk renamed the Texas Bunch the Texas Outlaws, with Kevin Von Erich standing with them, and both of them put Kevin's Star Wars loss on Ric Flair. Mark Canterbury's promo from Star Wars aired, and he says he's done managing."], ["p", "Kerry Von Erich admitted the loss to Bret Hart is eating at him. Eddie Marlin then walked in and gave him Andre the Giant in the main event of Saturday's live TV from the Mid South Coliseum. The Control Center laid out the rest of the tour: Diamond Studd's first match against Dennis Condrey on Saturday, Bill Dundee defending the TV Title against Chris Adams in Evansville on July 10, and Kerry and Bret teaming against Andre and Jamie Dundee in Louisville on July 13, with Steve Austin against Studd on the same card."]], "facts": [["Date", "Wed, July 3, 1991"], ["Venue", "Earl Bell Community Center, Jonesboro"], ["Crowd", "600"], ["Gate", "$3,000 · $5 avg"], ["Card rating", "***"], ["Best match", "Guerrero d. Zakowski, ***1/2"]], "factTitle": "The Show"}, "uswa-bret-kerry": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Unified Title", "title": "Bret & Kerry", "dek": "Bret Hart beat Kerry Von Erich at Star Wars and they shook hands. Kerry says it's eating at him. Now they're partners in Louisville and opponents again in Dallas.", "body": [["p", "The Unified Title program between Bret Hart and Kerry Von Erich has carried the USWA all summer, and Star Wars didn't end it. Bret won in 30:16 with the Sharpshooter (****1/4). Kerry raised his hand afterward. Everybody in the building could see Kerry didn't mean it."], ["h", "How they got here"], ["p", "It's been a strange feud because neither man is a heel. In June, Jerry Lawler spent weeks in Kerry's ear, telling him the Harts wanted to expose his weaknesses, and Kerry lost the June 22 cage match where he and Bret were partners against Lawler and Dutch Mantell. Bret tried to apologize afterward. Kerry wouldn't take it. Bret clapped for Kerry from the entrance after Kerry beat Lawler. On the June 29 TV they came face to face for the last time before Star Wars, and Kerry turned down the apology again."], ["h", "After Star Wars"], ["p", "On Worldwide July 3, Kerry was more honest than he's been all summer. He said he gave Bret everything and it wasn't enough, and that he can't figure out what he left in the ring. Then Eddie Marlin gave him Andre the Giant in the main event of the live Mid South Coliseum TV on July 6."], ["p", "That's a hard first assignment for a guy who just lost the biggest match of his year. Andre has been Paul Ellering's weapon all summer. He beat Bill Dundee by count-out in June, and Ellering's people laid out Toshiaki Kawada after Kawada turned the group down."], ["h", "Partners, for now"], ["p", "Here's the twist. On July 13 in Louisville, Bret and Kerry team up against Andre and Jamie Dundee. Neither of them asked for it, and they still haven't settled anything. After that, the calendar has the rematch everyone wants: Bret against Kerry in a 60-minute Iron Man match at Reunion Arena in Dallas on August 17, the USWA's first show in the building."], ["p", "The question for the next six weeks is simple. Can Kerry stop doubting himself before Dallas, and will Bret trust him enough in Louisville to find out?"]], "facts": [["Champion", "Bret Hart (Unified)"], ["Star Wars", "Bret by Sharpshooter, 30:16, ****1/4"], ["Next for Kerry", "Andre, Memphis 7/6"], ["Partners", "vs. Andre & Jamie Dundee, Louisville 7/13"], ["Big one", "Iron Man II, Reunion Arena 8/17"]], "factTitle": "The Program"}, "uswa-texas-outlaws": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Worldwide · Jonesboro, July 3", "title": "The Texas Outlaws", "dek": "Terry Funk buried the Texas Bunch and renamed his group the Texas Outlaws, with Kevin Von Erich at his side. Kevin blames Ric Flair for how he got there.", "body": [["p", "The Texas Bunch is gone. On Worldwide July 3, Terry Funk walked out with Chris Adams, Eric Embry, Tom Prichard and Kevin Von Erich and announced that the group is now the Texas Outlaws. Funk's line was that \"Texas Bunch\" sounded like something you'd sell at a church picnic."], ["p", "The pitch is that every man in the group got run out of somewhere when World Class went under, and now they're back and angry. The crowd booed, especially when Embry waved the World Class flag he draped over Sweet Daddy Falcone at Star Wars."], ["h", "Kevin keeps his word"], ["p", "Funk spent June recruiting Kevin, first in comments taped in Japan and then with a scuffle on TV. The stipulation for Star Wars was that if Kevin lost, he'd join. He lost, passing out in the spinning toe hold at 26:31 in the match of the night (*****1/4)."], ["p", "Kevin said in Jonesboro that his father raised him to keep his word. He also said Terry didn't beat him. Ric Flair did. Flair walked to ringside late in the match, Kevin looked at him, and Funk locked on the hold."], ["h", "A problem for Flair"], ["p", "Funk didn't sound happy about the help either. He said he never asked for anything from Ric Flair, that the two of them go back a long way, and that if Flair wants to play games with his family he'll have to deal with all of them. That puts Flair, who still has the Big Gold belt, in the sights of a five-man group right out of the gate."], ["p", "The Outlaws won their first match under the new name later that night when Adams beat newcomer Jim Powers with the superkick. Adams challenges Bill Dundee for the TV Title in Evansville on July 10."]], "facts": [["Leader", "Terry Funk"], ["Members", "Chris Adams, Eric Embry, Tom Prichard, Kevin Von Erich"], ["Ally", "Dutch Mantell (Star Wars eight-man)"], ["Renamed", "Worldwide, Jonesboro 7/3"], ["Target", "Ric Flair"], ["Next", "Adams vs. Bill Dundee, TV Title, 7/10"]], "factTitle": "The Outlaws"}, "uswa-studd-austin": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Southern Title", "title": "Studd vs. Austin", "dek": "The diamonds, the notes and the necklace all led to one man. Diamond Studd came over the rail at Star Wars, and Steve Austin thinks Missy Hyatt knew all along.", "body": [["p", "For a month, somebody has been messing with Steve Austin's head. Diamonds went missing from the new robe Missy Hyatt helped him pick out. Missy got a necklace she thought was from Austin, and it wasn't. A card turned up in his locker room that said \"Diamonds cut deep.\" On the June 29 TV a diamond distraction cost him a fall against Brickhouse Brown."], ["p", "At Star Wars on July 1 we found out who it was. Austin kept the Southern Title over Brickhouse with the Stun Gun after the Gilberts got involved (***). Hot Stuff International kept beating on Brickhouse after the bell, and Austin was whipping him with the belt when Diamond Studd came out of the crowd and cleared the ring."], ["h", "Austin vs. Missy"], ["p", "The notes were Studd's warning that he was coming for the title. Austin turned on Missy right there and accused her of being in on it. She swore she wasn't. He doesn't believe her, and inside a stable that also has the Gilberts and Dennis Condrey, that kind of paranoia is going to cause problems."], ["h", "What's next"], ["p", "Studd has his first USWA match on the live Memphis TV on July 6 against Condrey, one of Austin's own people. Then he gets Austin himself in Louisville on July 13. It's non-title, but after the way Star Wars ended, neither man is going to treat it that way."], ["p", "Brickhouse is still in this too. He's been chasing Austin all summer, and he'll want his own piece of Studd before anyone settles who gets the title shot."]], "facts": [["Champion", "Steve Austin (Southern)"], ["Star Wars", "Austin d. Brickhouse Brown (Stun Gun)"], ["Debut", "Diamond Studd, 7/1"], ["Studd's first match", "vs. Dennis Condrey, Memphis 7/6"], ["Next", "Austin vs. Studd, non-title, Louisville 7/13"]], "factTitle": "The Southern Title"}, "uswa-jarrett-gilberts": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Hot Stuff International", "title": "Jarrett vs. the Gilberts", "dek": "Eddie Gilbert won the cage at Star Wars and Hot Stuff International got the rub. Jeff Jarrett lost the war but still has a title shot in his pocket.", "body": [["p", "Jeff Jarrett has spent the whole summer fighting Hot Stuff International more or less by himself. It started with a falls-count-anywhere match against Doug Gilbert in early June, and it got personal when Eddie Gilbert started paying people to take Jarrett out. Footage showed Eddie paying Tom Prichard. Then Eric Embry took Eddie's money to finish Jarrett off."], ["h", "Louisville and the cage"], ["p", "Jarrett got his hands on Eddie in a no-holds-barred match at Friday Night Fights in Louisville on June 28 and won it, which made him the number-one contender to the Unified Title. He didn't get to enjoy it. Embry, Doug Gilbert and Prichard left him laying, and a bloody Jarrett asked for a cage."], ["p", "He got it at Star Wars, and it didn't go his way. Eddie slammed him throat-first into the mesh and then hit a piledriver through the ropes for the pin at 7:58. Four and a quarter stars. It was the best win of Eddie's USWA run and it put Hot Stuff International right next to the main event."], ["h", "Where it stands"], ["p", "Jarrett is still the number-one contender. That shot against Bret Hart is the one thing the Gilberts couldn't take from him. Eddie, meanwhile, has a new problem: Steve Austin is the star of the stable, Austin has stopped trusting Missy Hyatt, and a big cage win usually makes a man think he deserves more. Keep an eye on how long the Gilberts and Austin stay on the same page."]], "facts": [["Star Wars", "Eddie Gilbert d. Jarrett, cage, 7:58"], ["Rating", "****1/4"], ["Finish", "Piledriver through the ropes"], ["Jarrett", "#1 contender, Unified Title"], ["HSI", "Austin, Eddie & Doug Gilbert, Condrey, Missy Hyatt"]], "factTitle": "The Feud"}, "uswa-honky-canterbury": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Grudge Report", "title": "Honky vs. Canterbury", "dek": "Mark Canterbury spent months trying to tame the Moondogs. At Star Wars they turned on him and joined the Honky Tonk Man. Canterbury says he isn't a manager anymore.", "body": [["p", "All spring, Mark Canterbury was the man trying to keep the Moondogs in line. Honky Tonk Man made fun of him for it on TV, and the two of them had been going back and forth since June."], ["p", "It came apart on the Star Wars pre-show. Canterbury beat Honky by DQ when Moondog Rex interfered (3/4*), and then the Moondogs turned on him. Canterbury took a chair to the back, and the Moondogs walked out with Honky."], ["h", "No more managing"], ["p", "Canterbury's promo from after the match aired on Worldwide on July 3, and it was the best thing he's done on TV. He said he dragged the Moondogs out of the gutter, called Honky a \"greasy, rhinestone reject\" hiding behind two rabid dogs, and promised to smash the guitar over his head. The key line was \"I ain't a manager anymore. I'm a man on a mission.\""], ["p", "Honky answered on the same show by beating Oliver Peters in 2:24 with the Shake, Rattle and Roll."], ["h", "The road to the cage"], ["p", "With Rex, Spot and Cujo all behind Honky, Canterbury is outnumbered three to one, and he's going to need help. The end point is already on the calendar: a steel cage match between Honky and Canterbury at the Mid South Coliseum on August 31, where the Moondogs can't get in."]], "facts": [["The turn", "Star Wars pre-show, 7/1"], ["Moondogs", "Rex, Spot, Cujo"], ["Canterbury", "\"I ain't a manager anymore\""], ["Honky 7/3", "d. Oliver Peters, 2:24"], ["Blow-off", "Steel cage, Memphis 8/31"]], "factTitle": "The Grudge"}, "uswa-sam-houston": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Worldwide · Jonesboro, July 3", "title": "A Different Sam Houston", "dek": "Sam Houston opened Worldwide without the smile or the hat wave. He says he's been overlooked, and he named Scotty Flamingo as the problem.", "body": [["p", "Sam Houston has been one of the most reliable babyfaces in the territory for years, and on July 3 in Jonesboro he sounded like a different person. He took the microphone from Corey Maclin before the introduction was finished and said he didn't come out to grin and wave."], ["p", "His complaint is that he never once argued about where he was on the card, and it got him overlooked. Two nights earlier at Star Wars, Houston and Rob Zakowski were the last team eliminated by the Nightmares in a four-corners match that went more than an hour, when Nightmare Ken Wayne pinned him with the Flying Stomp at 1:06:21."], ["h", "Flamingo"], ["p", "Houston blamed the locker room's problems on loudmouths with shiny robes and named Scotty Flamingo. Flamingo has spent the summer interfering in other men's matches. He cost Toshiaki Kawada and ran his mouth through the TV Title tournament. Houston said that kind of thing poisons a dressing room and that from now on he's taking what's his."], ["p", "He walked out without acknowledging the crowd. Whether that's a man who's fed up or a man who's turning is the question, and Flamingo is almost certainly going to have something to say about it."]], "facts": [["Where", "Worldwide, Jonesboro 7/3"], ["Star Wars", "Pinned by Ken Wayne at 1:06:21"], ["Target", "Scotty Flamingo"], ["Status", "Babyface with a new edge"]], "factTitle": "The Interview"}, "uswa-power-pro": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Power Pro Wrestling · Nashville", "title": "Power Pro Wrestling: Level Up!", "dek": "The USWA's new development brand debuted in Nashville the night before Star Wars, and Rocky Johnson showed up in Memphis the next night.", "body": [["p", "The USWA launched Power Pro Wrestling: Level Up! with its first episode in Nashville on June 30. It's a separate show with its own roster, built as a training ground for young wrestlers. Some of them will get called up to USWA TV, but not all of them."], ["h", "Episode 1"], ["p", "The debut card was a list of names to remember. Tony Devito, Mike Modest and Mike Awesome were in a three-way. Marcus Alexander Bagwell faced Johnny B. Badd, the Thrillseekers took on veterans Buzz Sawyer and Ron Bass, Tatanka faced Glenn Gilbertti, and D-Von Dudley faced Simon Diamond. Scott Taylor of the USWA showed up after Mike Quackenbush vs. Shane Helms, which tells you the two rosters aren't going to stay apart."], ["h", "Rocky Johnson"], ["p", "Rocky Johnson talked on the show about the talent in Power Pro and about being back in the territory, and Simon Diamond told him he was the man he'd been waiting for. The next night, Michael St. John introduced Johnson to the Star Wars crowd as a special guest. It looks like he's going to be the face of the academy and a mentor to the young roster."], ["h", "What's next"], ["p", "Episode 2 tapes later this month. The early buzz is on Modest, Bagwell and Badd, and the obvious question is which of them gets the first call-up to USWA television."]], "facts": [["Launched", "S1E1, Nashville, June 30"], ["Role", "USWA development brand"], ["Mentor", "Rocky Johnson"], ["Names to watch", "Modest, Awesome, Bagwell, Badd, Thrillseekers"], ["Next", "Episode 2, late July"]], "factTitle": "The Brand"}, "uswa-flair-signs": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-02", "region": "Memphis Report", "kicker": "USWA · Star Wars 1991 · Memphis, July 1", "title": "Flair Crashes Star Wars", "dek": "Ric Flair's USWA debut came from ringside, not the ring. He cost Kevin Von Erich the match of the night. Bret Hart kept the Unified Title in a 30-minute war with Kerry. And three more new faces showed up before the night was over.", "body": [["p", "Star Wars drew 10,085 to the Mid South Coliseum on July 1 for $121,020, and the crowd got its money's worth. The card came in at three and a quarter stars overall, with four matches at four-plus. But the thing everyone left talking about was a man who never laid a hand on anybody."], ["h", "The Nature Boy arrives"], ["p", "Terry Funk and Kevin Von Erich went 26:31 in what was easily the match of the night. Late in it, Ric Flair walked down to ringside. Kevin looked at him for one second too long, Funk got the spinning toe hold locked in, and Kevin passed out. Flair's first act in the USWA was to cost a Von Erich a match in front of a sold-out Memphis crowd."], ["p", "It got worse for Kevin afterward. He is now officially part of Funk's Texas Bunch, and the show went off the air on a three-way staredown: Flair on one side, Funk and Kevin on the other. Flair still has the Big Gold belt. Nobody in the office has said yet what that means for the Unified Title, but his first targets look like they're standing in the Texas Bunch's corner."], ["h", "Bret keeps the gold"], ["p", "The main event was Bret Hart against Kerry Von Erich for the Unified Title, and it went 30:16 before Bret locked on the Sharpshooter and Kerry submitted. Four and a quarter stars. They shook hands afterward, and Kerry raised Bret's arm. But anyone watching Kerry's face saw a man who was frustrated with himself and starting to doubt whether he can beat Bret at all. That's the story to watch heading to Dallas and the Iron Man rematch on August 17."], ["h", "Studd shows his hand"], ["p", "Steve Austin kept the Southern Title over Brickhouse Brown with the Stun Gun, but only after the Gilberts got involved. Then Diamond Studd came over the rail and cleared Hot Stuff International out of the ring. Those mystery notes Austin has been getting? They were Studd's warning. Austin turned on Missy Hyatt and accused her of knowing. She says she didn't. He doesn't believe her."], ["h", "Everything else"], ["p", "Eddie Gilbert beat Jeff Jarrett in the cage with a piledriver through the ropes, a four-and-a-quarter-star match and a big win for HSI. Jarrett still holds the number-one contender's spot he won from Gilbert in Louisville."], ["p", "Tully Blanchard debuted as Scott Steiner's surprise partner after referee Downtown Bruno ruled Robert Fuller couldn't team with him. Steiner beat Dan Spivey by DQ when Spivey choked him out. It was short and messy, but the tag division finally has a direction."], ["p", "El Hijo Del Santo debuted on the pre-show and stole it, submitting Scott Taylor with the surfboard in 18:40 at four and a quarter stars. On the same pre-show, the Moondogs turned on Mark Canterbury and joined the Honky Tonk Man, which sets up the cage match on August 31."], ["p", "The Nightmares won the four-corners tag match in a marathon that went over an hour. The Texas Bunch and Dutch Mantell beat Jerry Lawler and the Memphis Mafia when Eric Embry piledrove Rex King and then draped a World Class flag over Sweet Daddy Falcone. Andre the Giant pinned Jimmy Valiant in Valiant's return. Michael St. John also introduced Rocky Johnson as a special guest, and it looks like he's being lined up as a mentor for Power Pro Wrestling."]], "facts": [["Attendance", "10,085 at the Mid South Coliseum"], ["Gate", "$121,020 ($12.00 avg.)"], ["Card rating", "***1/4"], ["Match of the night", "Terry Funk d. Kevin Von Erich (26:31)"], ["Retained", "Bret Hart (Unified), Steve Austin (Southern)"], ["Debuts", "Ric Flair, Diamond Studd, Tully Blanchard, El Hijo Del Santo"]], "factTitle": "Star Wars by the Numbers"}, "uswa-observer-evansville-0710": {"p": "uswa", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-11", "region": "Memphis Report", "kicker": "USWA · Worldwide · Evansville, July 10", "title": "Match Observations: Evansville", "dek": "Evansville draws 2,000 for $16,000. The promos carry a **1/2 show, Falcone gives Flamingo the match of the night, and Bill Dundee reaches for a piledriver.", "factTitle": "The Numbers", "facts": [["Venue", "Veterans Memorial Coliseum, Evansville, IN"], ["Date", "July 10, 1991 · Worldwide S1 E12"], ["Attendance", "2,000"], ["Average ticket", "$8.00"], ["Gate", "$16,000 + $1,000 merch"], ["Card rating", "**1/2"], ["Best match", "Flamingo d. Falcone, ***1/2"]], "body": [["h", "The gate and the card"], ["p", "USWA Worldwide taped in Evansville on 7/10 before 2,000 paying $16,000, plus about $1,000 in merchandise, a good number for a Wednesday TV taping and more than three times the 600 they drew in Jonesboro on 7/3. Card rated **1/2. The talk segments carried the show. The wrestling was mostly fine and only one match stood out."], ["h", "Flamingo and Falcone"], ["p", "That match was Scotty Flamingo vs. Sweet Daddy Falcone at ***1/2, and it opened the show. Flamingo announced his \"Flamingo Invitational Series,\" a weekly open challenge, and then had the best match of the night with a guy most people figured was there to do a job. Flamingo won clean with a flying sunset flip at 8:14. The interesting part is there was no cheating. He's a heel on the mic and he beat Falcone straight up, which either means they want the Invitational matches to make him look good or someone forgot. Either way, putting Flamingo in a weekly showcase spot is a good idea if Falcone-level matches are what they get."], ["h", "The Moondogs and Canterbury"], ["p", "The Moondogs beat Jos LeDuc and Kerry Brown in 5:13 when Rex pinned Brown with the bone. Using LeDuc and Brown as the opponents rather than prelim guys gave the squash a little more weight. The Honky Tonk Man promo afterward set up Spot vs. Mark Canterbury for 7/17 in Jonesboro, and Canterbury running the heels off was a good, simple angle. Canterbury as the wronged babyface is exactly what the Moondog turn at Star Wars was meant to set up."], ["h", "Jim Powers"], ["p", "Jim Powers got his first win over Rob Zakowski with a flying cross body at 8:04, **1/2. It was added for time and it filled time."], ["h", "The main event"], ["p", "The main event was Bill Dundee retaining the TV title over Chris Adams at 17:10, **1/2. For two guys this good, that's a letdown. It went long, and long isn't the same as good. The finish was Dundee piledriving Adams, which is notable. Dundee isn't a piledriver guy, and in this territory the piledriver has always been treated as something special, so it reads as Dundee getting meaner because of what Jamie did. If that's the intent, it's subtle storytelling. If it isn't, it just looked like a big babyface using a heel's move. Dundee keeps the belt for the 8/3 match with Jamie in Memphis, which is the right call."], ["h", "The promos"], ["p", "The promos were the strength of the show. Kerry Von Erich's was his best in some time, humble without being defeated, and it sets up Saturday's tag with Bret Hart against Andre and Jamie in Louisville. Bret's \"I respect him, but I beat him\" line keeps the Kerry program alive. Hansen and Spivey asked for a dog collar rematch for the tag titles with no DQ, which is the obvious follow-up to the Star Wars disqualification."], ["h", "Hot Stuff International"], ["p", "The most interesting thing on the show was a Hot Stuff International locker room scene. Eddie Gilbert told Steve Austin there are \"bigger prizes\" than the Southern title, Austin squared up, and Missy Hyatt played peacemaker in both directions. Nobody is saying a split is coming, but Gilbert sounds like a guy with his eye on more than the Southern belt, and he's coming off a cage win over Jeff Jarrett at Star Wars. Watch where that goes."], ["h", "Next: Louisville"], ["p", "The Control Center pushed Louisville on Saturday: Bret Hart & Kerry Von Erich vs. Andre the Giant & Jamie Dundee, Austin vs. Diamond Studd non-title, Hansen & Spivey, and a Ric Flair announcement about his ring debut. That's a much better lineup on paper than this show was."]]}, "uswa-diary-falcone-0710": {"p": "uswa", "series": "diary", "by": "Sweet Daddy Falcone", "date": "1991-07-10", "place": "US 41, heading south out of Evansville", "kicker": "From the Road · Evansville, July 10", "title": "The Good Trunks", "dek": "Sweet Daddy Falcone was invited to lose to Scotty Flamingo. He lost, and he stole the show doing it.", "factTitle": "The Night", "facts": [["Show", "USWA Worldwide, Evansville"], ["Match", "Scotty Flamingo d. Sweet Daddy Falcone"], ["Finish", "Flying sunset flip, 8:14"], ["Rating", "***1/2, match of the night"]], "body": [["p", "Got the call this afternoon. Scotty Flamingo wanted an opponent for his new \"Invitational.\" I knew what that meant. They don't invite you to these things to win. You go out, you make the young guy look like a million bucks, you take the pin, you get in the car."], ["p", "So I put on the good trunks anyway."], ["p", "Flamingo comes out in that pink jacket and gets on the mic and tells two thousand people in Evansville that I've been around too long. Too long. I've been around long enough to know that when a kid says that, he's scared you're going to show him something. So I showed him something."], ["p", "Eight minutes and change. I had him rolled up twice. I had that crowd, too. They came in booing him and by the end half of them were chanting for me. Me. The guy who got a World Class flag thrown over his head at Star Wars nine days ago. You could feel it go through the building."], ["p", "And then the little peacock comes off the top rope, flips over me, and rolls me up, and that's that. One, two, three. Flying sunset flip. I'll give him this: he didn't pull the tights. Scotty Flamingo, the biggest mouth in the territory, beat me clean. I'm not sure he knows how much that says about him. I think the kid can go."], ["p", "Walking back through the curtain, a couple of the boys gave me a nod. That's worth more to me than the payoff. Bill Dundee shook my hand on his way out to the main event. He had that look on his face, the one a man gets when family business is eating him alive. He went out and dropped Chris Adams on his head with a piledriver. I've known Bill a long time. I never saw him do that before."], ["p", "Flamingo says there's a new invitation every week. Well, I already got mine. I'll be watching to see if anybody else gives him a better match than I did tonight."], ["p", "Long drive home. Radio's playing nothing but static. Doesn't matter. Tonight I was the match of the night, and nobody in that building is going to forget it for a while. Maybe that's all you get in this business. Maybe that's enough."]]}, "uswa-observer-jonesboro-0703": {"p": "uswa", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-04", "region": "Memphis Report", "kicker": "USWA · Worldwide · Jonesboro, July 3", "title": "Match Observations: Jonesboro", "dek": "The Red, White and Bruised Tour opens before 600 in Jonesboro. Eddie Guerrero has the match of the night, the Texas Bunch become the Texas Outlaws, and Sam Houston stops smiling.", "factTitle": "The Numbers", "facts": [["Venue", "Earl Bell Community Center, Jonesboro, AR"], ["Date", "July 3, 1991 · Worldwide S1 E11"], ["Attendance", "600"], ["Average ticket", "$5.00"], ["Gate", "$3,000.00"], ["Card", "***"]], "body": [["p", "The Red, White and Bruised Tour opened at the Earl Bell Community Center, and the 600 fans in Jonesboro got a card that set the table for the busiest month of the summer. The show earned three stars overall, and the biggest stories were told with a microphone."], ["p", "In the main event, the Boogie Woogie Man made a winning return to television. Jimmy Valiant and Bill Dundee got the better of Dirty White Boy and Rex King of the Memphis Mafia in a hard-hitting ten minutes. Valiant cut off a Rex King comeback, locked in the sleeperhold, and King had no choice but to give it up. Three stars. Two days after Star Wars, the Mafia have now come up short on back-to-back nights."], ["p", "The match of the night came early. Eddie Guerrero and Rob Zakowski traded holds and near falls for eleven minutes before Guerrero went to the top rope and hit the frog splash for the win. Three and a half stars. Guerrero continues to turn heads every time he steps through the ropes."], ["p", "Chris Adams welcomed newcomer Jim Powers to the USWA the hard way. Powers showed fire and power in the early going, but Adams caught him with the superkick at 5:27. The win came minutes after Adams stood with Terry Funk as the Texas Bunch rebranded as the Texas Outlaws, with Kevin Von Erich officially in the fold. Kevin says he kept his word to Funk, but he also put the blame for his loss squarely on Ric Flair."], ["p", "Honky Tonk Man needed only 2:24 to put away Oliver Peters with the Shake, Rattle and Roll. Earlier, fans saw Mark Canterbury's emotional promo from Star Wars, and Canterbury made it clear he is no longer a manager. He wants the Moondogs and he wants Honky Tonk Man."], ["p", "The New Kids and Scott Taylor rolled past Jan Vang, Jody Burt and Johnny Rich. Tony Williams finished it with a flying cross body on Rich at 6:15."], ["p", "Sam Houston opened the show and the crowd barely recognized him. No smile, no hat wave. Houston called out Scotty Flamingo for poisoning the locker room and promised to start taking what's his."], ["p", "Fans also saw highlights of Ric Flair's arrival at Star Wars. The Nature Boy cost Kevin Von Erich his match with Funk and stood face to face with both men to close the show. Nobody knows yet what Flair wants."], ["p", "Kerry Von Erich admitted the loss to Bret Hart is eating at him. Then Eddie Marlin gave him the chance he asked for: Saturday night at the Mid South Coliseum, live on TV, Kerry Von Erich against Andre the Giant."]]}, "uswa-observer-memphis-0706": {"p": "uswa", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-08", "region": "Memphis Report", "kicker": "USWA · Backstage Notes", "title": "Backstage Notes: Memphis", "dek": "Memphis did $54,000 and an angle show. Flair has everybody guessing, Tully gets the belt, Jamie Dundee gets a chain, and Kawada goes home.", "body": [["h", "The gate"], ["p", "The Memphis TV on 7/6 drew 4,500 to the Mid South Coliseum at a $12 average ticket for a $54,000 gate, plus about $2,000 in merchandise. That's a big drop from the 10,085 sellout for Star Wars five days earlier, but it's a normal Saturday for this building, and it's live television. The card came in at **1/2. Andre vs. Kerry was the best thing on it at **3/4, which tells you how thin the wrestling was. This was an angle show, and the angles were good."], ["h", "Andre and Kerry"], ["p", "The main event did what it was supposed to do. Andre's mobility is very limited, and they kept Kerry selling for most of the 14:43 rather than asking Andre to do much. The bear hug finish protects Kerry, since he never quit, and it gives Ellering's group a big win going into the Louisville tag match. Andre has been the guy in Ellering's corner all summer, and the office is clearly building that group up before Hansen and Spivey formally join later this month."], ["h", "Flair"], ["p", "The Flair angle after the match is the story of the week. Nobody outside the office seems to know where this is going. The theory going around is that Flair is setting up the Von Erich brothers against each other, with Kevin now in Terry Funk's Texas Outlaws and Kerry still floating on his own after losing to Bret. Flair's first in-ring match is expected against Funk in Dallas on 7/20, and Dallas is Von Erich country. Watch the Sportatorium number."], ["h", "The tag titles"], ["p", "The Steiner and Blanchard announcement was the right call. Tully is a proven tag team wrestler, and Steiner needed a credible partner after Rick left for WCW. The Fuller tension gives the office a babyface-turned-jealous story without hurting the champions, and it keeps Fuller busy until the Canterbury and Moondogs program needs him."], ["h", "Diamond Studd"], ["p", "Diamond Studd's debut match went seven minutes, longer than a squash should. It was *1/2. Studd's look and promo work are what's getting him over, and the backstage segment with Missy Hyatt and Steve Austin was strong. Austin playing the paranoid champion who doesn't trust his own valet is working, and Missy's look down the hallway after Studd is a seed for later."], ["h", "Jamie Dundee"], ["p", "The Jamie Dundee chain attack on Jimmy Valiant got heat. Jamie is still green in the ring, but he's a Dundee, and this is the angle that could make him. Bill Dundee defending the TV Title against Chris Adams on Wednesday is the first test of whether fans will pay to see the father go after the son."], ["h", "The six-man"], ["p", "The six-man was fine. El Hijo Del Santo was in on a free night from CMLL. Eddie Guerrero couldn't make the trip because he was booked on the Saturday show at Arena Mexico, where the gate was $41,040, less than Memphis did. Scott Taylor got the pin on the Masked Avenger with a Fall of the Angels, and the office likes him. Taylor and Santo working each other again is something people want to see."], ["h", "Roster moves"], ["p", "Backstage, a few roster changes. Rex King has re-signed and stays with the Memphis Mafia. Moondog Cujo's deal is up and he won't renew, which matters because the plan for the Moondogs and Mark Canterbury had a Cujo match in it, so that program will be reworked with Rex or Spot. Toshiaki Kawada wanted to stay, but All Japan asked for him back for its tour, and Baba isn't the type you say no to. Ellering mentioned it on TV as Kawada's loss, which closes that thread neatly."], ["h", "Business"], ["p", "Business for the week of July 1 is strong. Star Wars did $121,020 at the Coliseum, the Jonesboro TV did $3,000, and Memphis did $54,000 plus merchandise, so the territory took in about $180,000 in seven days. The next big number is Louisville Gardens on 7/13, which seats about 6,000. Kerry and Bret teaming against Andre and Jamie, with Austin vs. Studd underneath, is a strong card for that building."]], "facts": [["Show", "Championship Wrestling, Memphis 7/6"], ["Gate", "$54,000 + ~$2,000 merch"], ["Card rating", "**1/2"], ["Best match", "Andre d. Kerry, **3/4"], ["Week of 7/1", "~$180,000 revenue"], ["Next", "Louisville Gardens, 7/13"]], "factTitle": "The Numbers"}, "uswa-bret-saves-kerry": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-08", "region": "Memphis Report", "kicker": "USWA · Championship Wrestling · Memphis, July 6", "title": "Andre Puts Kerry to Sleep", "dek": "Kerry Von Erich asked for Andre and passed out in the bear hug. Then Ric Flair walked into the ring to check on him, and nobody knows why.", "body": [["p", "The live Championship Wrestling TV from the Mid South Coliseum on July 6 drew 4,500 for $54,000, plus about $2,000 in merchandise. It was a normal Saturday house after the Star Wars sellout, and the card came in at **1/2. It was an angle show, and the angles were good."], ["h", "The main event"], ["p", "Andre the Giant, with Paul Ellering, beat Kerry Von Erich at 14:43 when Kerry passed out in the bear hug (**3/4). Kerry never quit; the referee dropped his arm three times. It protects Kerry and gives Ellering's group a big win before Louisville, where Kerry and Bret Hart team against Andre and Jamie Dundee on July 13."], ["h", "Flair again"], ["p", "After the bell, Ric Flair walked down in a suit with the Big Gold belt, waved off the officials, helped Kerry sit up and said something in his ear the cameras couldn't hear. Then he left. Five days earlier he cost Kevin Von Erich his match with Terry Funk. The theory going around is that Flair is working the brothers against each other. His first match is expected against Funk in Dallas on July 20."], ["h", "Everything else"], ["p", "Scott Steiner officially made Tully Blanchard his partner, and Eddie Marlin recognized them as the USWA Tag Team Champions. Robert Fuller, who stood by Steiner after Rick left, went nose to nose with Blanchard and walked out."], ["p", "Diamond Studd's first USWA match was a 7:04 win over Dennis Condrey with the Final Reckoning (*1/2). Backstage he turned down Missy Hyatt and Steve Austin's offer to join Hot Stuff International, and Austin didn't like how friendly Missy was with him. Austin and Studd meet, non-title, in Louisville."], ["p", "Jamie Dundee said his father picked Jimmy Valiant over his own blood, then attacked Valiant with a chain backstage. Sam Houston beat Johnny Rich and ran Scotty Flamingo off. Scott Taylor and the New Kids beat El Hijo Del Santo, the Spellbinder and the Masked Avenger."], ["h", "Roster"], ["p", "Rex King has re-signed. Moondog Cujo's contract is up and he won't renew. Toshiaki Kawada wanted to stay, but All Japan asked for him back; Ellering called it Kawada's loss on TV."]], "facts": [["Attendance", "4,500 at the Mid South Coliseum"], ["Gate", "$54,000 ($12 avg.) + $2,000 merch"], ["Card rating", "**1/2"], ["Main event", "Andre d. Kerry Von Erich (bear hug), **3/4"], ["Angle", "Flair checks on Kerry"], ["Next", "Louisville Gardens, July 13"]], "factTitle": "The Show"}});

CONTRACTS.uswa = {"basis": "Weekly, per appearance", "unit": "per appearance (TV rate)", "revenue": "About $20–25K per card in a normal month; about $28–30K with a supershow every 6–8 weeks. Star Wars drew $121,020; Reunion Arena is projected at $320,000.", "target": "Weekly payroll at or under 40% of that week's gate.", "how": "Each appearance pays the base rate × the show multiplier. Arena shows and supershows add a cut of the gate for the main event and semi-main, split evenly among the wrestlers in the match. Paid weekly for every show the wrestler is on. Managers and announcers are on the same scale.", "classes": [["TV taping / spot show", "Worldwide (Jonesboro, Evansville), syndicated tapings", "1×", "—", "—"], ["Arena show", "Mid South Coliseum Saturdays, Louisville Gardens, Sportatorium, Friday Night Fights", "2×", "10% of gate", "5% of gate"], ["Supershow", "Star Wars, Reunion Arena, Autumn Armageddon", "3×", "12% of gate", "6% of gate"]], "example": "Week of July 1–6: $178,020 gate, $53,279 payroll (30%). Top checks: Kerry Von Erich $11,911, Bret Hart $8,386, Andre $4,700, Ric Flair $3,125.", "rows": [["A", "Ric Flair", 625, ""], ["A", "Andre the Giant", 400, ""], ["A", "Bret Hart", 375, ""], ["A", "Kerry Von Erich", 325, ""], ["A", "Terry Funk", 275, ""], ["A", "Kevin Von Erich", 275, ""], ["A", "Jerry Lawler", 250, ""], ["B", "Stan Hansen", 225, ""], ["B", "Eddie Gilbert", 175, ""], ["B", "Steve Austin", 150, ""], ["B", "Jeff Jarrett", 150, ""], ["B", "Scott Steiner", 150, ""], ["B", "Tully Blanchard", 150, ""], ["B", "Dan Spivey", 150, ""], ["B", "Bill Dundee", 125, ""], ["B", "Diamond Studd", 125, ""], ["B", "Robert Fuller", 125, ""], ["B", "Dutch Mantell", 110, ""], ["C", "Sam Houston", 90, ""], ["C", "Chris Adams", 85, ""], ["C", "Doug Gilbert", 85, ""], ["C", "Dennis Condrey", 85, ""], ["C", "Honky Tonk Man", 85, ""], ["C", "Brickhouse Brown", 75, ""], ["C", "Scotty Flamingo", 75, ""], ["C", "Toshiaki Kawada", 75, "Leaving: AJPW recalled him"], ["C", "Dirty White Boy", 60, ""], ["C", "Jimmy Valiant", 60, ""], ["C", "Eric Embry", 60, ""], ["C", "Tom Prichard", 60, ""], ["C", "Mark Canterbury", 60, ""], ["C", "Eddie Guerrero", 60, ""], ["C", "El Hijo Del Santo", 60, ""], ["C", "Dick Slater", 60, ""], ["D", "Nightmare Danny Davis", 50, ""], ["D", "Nightmare Ken Wayne", 50, ""], ["D", "Jamie Dundee", 50, ""], ["D", "Moondog Rex", 50, ""], ["D", "Rex King", 45, "Re-signed 7/91: 150 cards"], ["D", "Moondog Spot", 45, ""], ["D", "The Spellbinder", 40, ""], ["D", "Moondog Cujo", 40, "Leaving: contract up, won't renew"], ["D", "Sweet Daddy Falcone", 40, ""], ["D", "Jim Powers", 40, ""], ["E", "Brian Christopher", 30, ""], ["E", "Tony Williams", 30, ""], ["E", "Scott Taylor", 30, ""], ["E", "Rob Zakowski", 30, ""], ["E", "The Masked Avenger", 20, ""], ["F", "Oliver Peters", 15, ""], ["F", "Red Tyler", 15, ""], ["F", "Alan Martin", 15, ""], ["M", "Paul Ellering", 150, "Manager: Andre, Hansen & Spivey, Jamie Dundee"], ["M", "Missy Hyatt", 125, "Manager: Hot Stuff International"], ["O", "Lance Russell", 150, "Host, Control Center"], ["O", "Dave Brown", 100, "Commentary and interviews"], ["O", "Corey Maclin", 60, "Interviewer"], ["O", "Michael St. John", 50, "Event Center, special announcements"]], "total": 6565, "check": "Week of July 1–6 at this scale: 30% of the gate."};

